def solve(inputs: dict) -> float:
    # Linear congruential generator: X = (a*X + c) mod m
    # Applied for n rounds
    X = inputs.get('initial_value', 283)
    a = inputs.get('multiplier', 800)
    c = inputs.get('increment', 2900)
    m = inputs.get('modulus', 33500)
    n = inputs.get('rounds', 9)

    for _ in range(n):
        X = (a * X + c) % m

    return float(X)
